#!/usr/bin/env node
import { expandUserPath } from './lib/paths.mjs';
import { readJsonFile } from './lib/json.mjs';
/**
 * Brand-core composer: zhongtai brand frame + PPT Master content layouts.
 *
 *   node scripts/compose-core.mjs <project> [--check] [--only P07] [--json]
 *
 * Fixed pages (cover / title / section / ending) are copied from the zhongtai
 * brand template. Content pages use the core-* layouts (06c/06d/06k/06cmp/
 * 06t/06s), which port PPT Master's content compositions into the brand safe
 * area while keeping the brand background, logo, title bar and page number.
 * TOC is skipped here and generated by build-toc.mjs.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');

const args = { _: [] };
for (let i = 2; i < process.argv.length; i += 1) {
  const item = process.argv[i];
  if (!item.startsWith('--')) { args._.push(item); continue; }
  const key = item.slice(2);
  const next = process.argv[i + 1];
  if (next && !next.startsWith('--')) { args[key] = next; i += 1; }
  else args[key] = true;
}

const project = path.resolve(expandUserPath(args._[0] || '.'));
const only = args.only ? String(args.only).toUpperCase().padStart(2, '0') : null;
const checkOnly = Boolean(args.check);
const jsonOut = Boolean(args.json);

const outlinePath = path.join(project, 'outline.json');
const templatePath = path.join(project, 'template.json');
if (!fs.existsSync(outlinePath)) { console.error(`[BLOCK] 没有 outline.json：${outlinePath}`); process.exit(1); }
if (!fs.existsSync(templatePath)) { console.error(`[BLOCK] 没有 template.json；先跑 prepare-core-project.mjs`); process.exit(1); }
const outline = readJsonFile(outlinePath);
const template = readJsonFile(templatePath);
if (outline.status !== 'confirmed') { console.error('[BLOCK] outline.json status 不是 confirmed'); process.exit(1); }
const slides = Array.isArray(outline.slides) ? outline.slides : [];
if (!slides.length) { console.error('[BLOCK] outline.json 没有 slides'); process.exit(1); }

const templatesDir = path.join(project, 'templates');
const outDir = path.join(project, 'svg_output');
const colors = template.constants?.colors || {};
const BRAND_RED = colors.brand || '#B20017';

const layouts = new Map();
for (const name of fs.readdirSync(templatesDir).filter((n) => n.endsWith('.svg'))) {
  const source = fs.readFileSync(path.join(templatesDir, name), 'utf8');
  const root = /<svg\b[^>]*>/i.exec(source)?.[0] || '';
  const key = /data-pptx-layout="([^"]*)"/.exec(root)?.[1] || name.replace(/\.svg$/i, '');
  layouts.set(key, { file: name, source });
}

const CORE_MAP = {
  cover: 'cover',
  title: 'title',
  toc: 'toc',
  section: 'section',
  ending: 'closing',
  summary: 'core-three-card',
  'cards-3': 'core-three-card',
  'metrics-4': 'core-kpi-evidence',
  'metrics-compare': 'core-comparison',
  structure: 'core-timeline',
  table: 'core-data-story',
  'table-metrics': 'core-data-story',
  'content-rich': 'core-data-story',
  content: 'core-data-story',
  'two-content': 'core-comparison',
  two_content: 'core-comparison',
};

function coreLayout(slide) {
  if (slide.role === 'toc') return 'toc';
  if (slide.role === 'section' && /title|项目名|project/i.test(String(slide.id))) return 'title';
  const explicit = slide.coreTemplate || slide.template;
  let key = CORE_MAP[explicit] || CORE_MAP[slide.role] || 'core-data-story';
  if ((explicit === 'cards-3' || explicit === 'summary') && slide.cards && slide.cards.length >= 4) {
    key = 'core-four-card';
  }
  if (!layouts.has(key)) throw new Error(`缺少品牌-core 版式：${key}`);
  return key;
}

// ── Text helpers ─────────────────────────────────────────────────────
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function widthOf(text) {
  let w = 0;
  for (const ch of String(text ?? '')) w += ch.codePointAt(0) <= 0x7f ? 0.55 : 1;
  return w;
}
function truncate(text, max) {
  const t = String(text ?? '');
  if (widthOf(t) <= max) return t;
  let out = '';
  let w = 0;
  for (const ch of t) {
    const cw = ch.codePointAt(0) <= 0x7f ? 0.55 : 1;
    if (w + cw > max - 1) break;
    out += ch; w += cw;
  }
  return out + '…';
}
function wrap(text, max) {
  const out = [];
  let line = '';
  let w = 0;
  const tokens = String(text ?? '').match(/[A-Za-z0-9×÷+\-./%:]+|\s+|[\s\S]/g) || [];
  for (const token of tokens) {
    const cw = widthOf(token);
    if (w + cw > max && line.trim()) { out.push(line); line = ''; w = 0; }
    line += token; w += cw;
  }
  if (line) out.push(line);
  const merged = [];
  for (const item of out) {
    const previous = merged[merged.length - 1];
    if (/^[，。；、）》】]/.test(item) && previous && widthOf(previous + item) <= max + 1) {
      merged[merged.length - 1] = previous + item;
    } else merged.push(item);
  }
  return merged;
}
function headOf(text) {
  const t = String(text ?? '').trim();
  const m = /^([^：:，,。；;]{2,10})[：:，,。；;]/.exec(t);
  return m ? m[1] : truncate(t, 8);
}
function stripHead(head, text) {
  const t = String(text ?? '');
  return head && t.startsWith(head) ? t.slice(head.length).replace(/^[：:，,。；;]\s*/, '') : t;
}

function slotBoundsFor(svg, token) {
  const index = svg.indexOf(`{{${token}}}`);
  if (index < 0) return null;
  const before = svg.slice(0, index);
  const open = before.lastIndexOf('<g ');
  if (open < 0) return null;
  const tagEnd = svg.indexOf('>', open);
  const tag = svg.slice(open, tagEnd + 1);
  const match = /data-pptx-bounds="([^"]+)"/.exec(tag);
  if (!match) return null;
  const [x, y, w, h] = match[1].trim().split(/\s+/).map(Number);
  return { x, y, w, h };
}
function textAttrs(svg, token) {
  const re = new RegExp(`<text([^>]*)>\\s*\\{\\{${token}\\}\\}\\s*</text>`);
  const match = re.exec(svg);
  if (!match) return null;
  const attrs = match[1];
  const x = /x="([^"]+)"/.exec(attrs)?.[1] || '64';
  const size = Number(/font-size="([^"]+)"/.exec(attrs)?.[1] || 19);
  const bounds = slotBoundsFor(svg, token);
  const maxUnits = bounds ? Math.max(4, Math.floor((bounds.w - 16) / (size * 1.06))) : 40;
  const maxLines = bounds ? Math.max(1, Math.floor((bounds.h - 8) / (size * 1.45))) : 10;
  return { re, attrs, x, size, maxUnits, maxLines };
}
function fillText(svg, token, value) {
  if (!svg.includes(`{{${token}}}`)) return svg;
  const t = textAttrs(svg, token);
  return svg.split(`{{${token}}}`).join(esc(t ? truncate(value, t.maxUnits) : value));
}
function fillRawText(svg, token, value) {
  return svg.split(`{{${token}}}`).join(esc(value));
}
function fillLines(svg, token, lines) {
  const t = textAttrs(svg, token);
  if (!t) return svg;
  const flat = [];
  for (const line of (Array.isArray(lines) ? lines : [lines])) {
    if (line === '') { flat.push(''); continue; }
    const parts = wrap(line, t.maxUnits);
    if (!parts.length) flat.push('');
    else flat.push(...parts);
  }
  const clipped = flat.slice(0, t.maxLines);
  const lineH = Math.round(t.size * 1.5);
  const spans = clipped.map((line, i) => `<tspan x="${t.x}" dy="${i === 0 ? 0 : lineH}">${esc(line)}</tspan>`).join('');
  return svg.replace(t.re, `<text${t.attrs}>${spans}</text>`);
}
function fillRichLines(svg, token, items) {
  const t = textAttrs(svg, token);
  if (!t) return svg;
  const lines = [];
  for (const item of items) {
    const parts = wrap(item.text, t.maxUnits);
    if (!parts.length) continue;
    lines.push({ text: parts[0], style: item.style });
    for (const part of parts.slice(1)) lines.push({ text: part, style: item.style });
  }
  const flat = lines.slice(0, t.maxLines);
  const lineH = Math.round(Math.max(t.size, 21) * 1.45);
  const spans = flat.map((line, i) => `<tspan x="${t.x}" dy="${i === 0 ? 0 : lineH}"${line.style ? ` ${line.style}` : ''}>${esc(line.text)}</tspan>`).join('');
  return svg.replace(t.re, `<text${t.attrs}>${spans}</text>`);
}

// ── Content derivation ───────────────────────────────────────────────
const evidenceOf = (slide) => (Array.isArray(slide.evidence)
  ? slide.evidence.filter(Boolean)
  : (slide.evidence ? [slide.evidence] : []));

function cardsOf(slide) {
  const evidence = evidenceOf(slide);
  if (slide.cards) {
    const cards = slide.cards.map((c) => {
      if (typeof c === 'string') return { head: headOf(c), body: [stripHead(headOf(c), c)] };
      const head = c.head || headOf(c.body);
      const body = Array.isArray(c.body) ? c.body : [c.body || ''];
      return { head, body: body.map((b) => stripHead(head, b)) };
    });
    cards.forEach((card, i) => {
      if (evidence[i] && card.body.join('').length < 80) card.body.push(evidence[i]);
    });
    return cards.slice(0, 4);
  }
  const points = (slide.points || []).filter(Boolean);
  const per = Math.ceil(Math.max(1, points.length) / 3);
  return [0, 1, 2].map((i) => {
    const slice = points.slice(i * per, (i + 1) * per);
    const head = slice.length ? headOf(slice[0]) : (slide.coreMessage || '核心判断');
    const body = slice.length ? slice.map((p) => stripHead(head, p)) : [slide.coreMessage || ''];
    if (evidence[i] && body.join('').length < 80) body.push(evidence[i]);
    return { head, body };
  });
}

function metricsOf(slide) {
  if (slide.metrics) return slide.metrics.slice(0, 4);
  const text = [slide.soWhat, ...evidenceOf(slide), ...(slide.points || [])].join(' ');
  const found = [...text.matchAll(/(\d+(?:\.\d+)?)\s*(ms|毫秒|G|核|张|%|秒|s|QPS)?/g)]
    .map((m) => ({ value: m[1], unit: m[2] || '', label: '', note: '' }))
    .slice(0, 4);
  return found.length >= 3 ? found : null;
}
function compareOf(slide) {
  if (slide.compare) return slide.compare;
  const points = (slide.points || []).filter(Boolean);
  const half = Math.ceil(points.length / 2);
  return {
    left: { head: '现状 / 方案 A', lines: points.slice(0, half) },
    right: { head: '目标 / 方案 B', lines: points.slice(half) },
  };
}
function contentLines(slide, maxLines = 12) {
  const lines = [];
  for (const p of (slide.points || [])) lines.push(`· ${p}`, '');
  for (const e of evidenceOf(slide)) lines.push(`· ${e}`, '');
  if (slide.soWhat) lines.push(`含义：${slide.soWhat}`);
  if (slide.action) lines.push(`下一步：${slide.action}`);
  return lines.slice(0, maxLines);
}
function tableLines(slide) {
  if (!slide.table) return contentLines(slide);
  const cols = slide.table.columns || [];
  const rows = slide.table.rows || [];
  return [
    cols.map((c) => c.label || '').join(' | '),
    ...rows.map((row) => row.join(' | ')),
  ].slice(0, 12);
}
function bodyChars(svg, slide, page) {
  const text = [...svg.matchAll(/<text[^>]*>(.*?)<\/text>/gs)]
    .map((m) => m[1].replace(/<[^>]+>/g, '')).join('');
  return text.length - String(slide.title || '').length - String(Number(page.slice(1))).length;
}

// ── Compose ──────────────────────────────────────────────────────────
const report = [];
const errors = [];
const warnings = [];
const contentSlides = slides.filter((s) => s.role === 'content');
const CN = ['一', '二', '三', '四', '五', '六', '七', '八', '九', '十', '十一', '十二', '十三', '十四', '十五'];
const chapterOf = new Map();
contentSlides.forEach((s, i) => chapterOf.set(s.id, `${CN[i] || (i + 1)}、`));

function composePage(slide, index) {
  const pageNo = index + 1;
  const page = `P${String(pageNo).padStart(2, '0')}`;
  const key = coreLayout(slide);
  if (key === 'toc') return null;
  const layout = layouts.get(key);
  let svg = layout.source;

  // Common brand slots (only replace when the layout has them).
  if (svg.includes('{{CHAPTER}}')) svg = fillText(svg, 'CHAPTER', chapterOf.get(slide.id) || '');
  if (svg.includes('{{PAGE_TITLE}}')) svg = fillText(svg, 'PAGE_TITLE', slide.title || '');
  if (svg.includes('{{PAGE_NUM}}')) svg = fillText(svg, 'PAGE_NUM', String(pageNo));

  if (key === 'cover') {
    // Brand cover is a full-bleed image with no text.
  } else if (key === 'title') {
    svg = fillText(svg, 'PROJECT_NAME', outline.contract?.projectName || slide.title || '');
    svg = fillText(svg, 'PROJECT_NO', slide.projectNo || '项目编号：待填写');
    svg = fillText(svg, 'DEPARTMENT', slide.department || '申报部门：待填写');
    svg = fillText(svg, 'DATE', slide.date || '2026 年 11 月');
  } else if (key === 'section') {
    svg = fillText(svg, 'SECTION_NO', chapterOf.get(slide.id) || '');
    svg = fillText(svg, 'SECTION_TITLE', slide.title || '');
    svg = fillText(svg, 'SECTION_SUB', slide.coreMessage || '');
  } else if (key === 'closing') {
    svg = fillText(svg, 'CLOSING_TEXT', slide.coreMessage || '谢谢聆听');
  } else if (key === 'core-three-card' || key === 'core-four-card') {
    const max = key === 'core-four-card' ? 4 : 3;
    const cards = cardsOf(slide).slice(0, max);
    cards.forEach((card, i) => {
      svg = fillRichLines(svg, `CARD_${i + 1}`, [
        { text: card.head, style: `font-size="21" font-weight="700" fill="${BRAND_RED}"` },
        ...card.body.map((line) => ({ text: line })),
      ]);
    });
    const take = slide.takeaway || slide.soWhat || '';
    if (take) svg = fillText(svg, 'TAKEAWAY', take);
  } else if (key === 'core-kpi-evidence') {
    const metrics = metricsOf(slide) || [];
    for (let i = 1; i <= 4; i += 1) {
      const m = metrics[i - 1] || {};
      svg = fillRawText(svg, `KPI_${i}`, `${m.value ?? ''}${m.unit ?? ''}`);
    }
    const lines = [
      ...metrics.map((m) => `${m.label || ''}${m.note ? `：${m.note}` : ''}`),
      ...evidenceOf(slide),
      slide.soWhat || '',
      slide.source ? `来源：${slide.source}` : '',
    ].filter(Boolean);
    svg = fillLines(svg, 'EVIDENCE', lines);
  } else if (key === 'core-comparison') {
    const metrics = metricsOf(slide) || [];
    for (let i = 1; i <= 4; i += 1) {
      const m = metrics[i - 1] || {};
      svg = fillRawText(svg, `KPI_${i}`, `${m.value ?? ''}${m.unit ?? ''}`);
    }
    const cmp = compareOf(slide);
    const evidence = evidenceOf(slide);
    const left = [...(cmp.left?.lines || []), ...(evidence[0] ? [evidence[0]] : [])];
    const right = [...(cmp.right?.lines || []), ...(evidence[1] ? [evidence[1]] : [])];
    svg = fillText(svg, 'LEFT_TITLE', cmp.left?.head || '方案 A');
    svg = fillText(svg, 'RIGHT_TITLE', cmp.right?.head || '方案 B');
    svg = fillLines(svg, 'LEFT_CONTENT', left);
    svg = fillLines(svg, 'RIGHT_CONTENT', right);
    const take = slide.takeaway || slide.soWhat || '';
    if (take) svg = fillText(svg, 'TAKEAWAY', take);
  } else if (key === 'core-timeline') {
    const steps = (slide.layers || []).slice(0, 4);
    const evidence = evidenceOf(slide);
    for (let i = 1; i <= 4; i += 1) {
      const step = steps[i - 1] || {};
      svg = fillRichLines(svg, `STEP_${i}`, [
        { text: step.name || `${i}`, style: `font-size="21" font-weight="700" fill="${BRAND_RED}"` },
        { text: [step.text, evidence[i]].filter(Boolean).join('；') },
      ]);
    }
    svg = fillText(svg, 'KEY_MESSAGE', slide.soWhat || slide.takeaway || '');
  } else if (key === 'core-data-story') {
    const lines = slide.table ? tableLines(slide) : contentLines(slide);
    svg = fillLines(svg, 'EVIDENCE', lines);
    svg = fillLines(svg, 'KEY_MESSAGE', [slide.soWhat || slide.takeaway || '']);
    svg = fillText(svg, 'SOURCE', slide.source || '');
  } else {
    errors.push(`${page}: 未实现的品牌-core 版式 '${key}'`);
  }

  if (/\{\{[A-Z0-9_]+\}\}/.test(svg)) {
    const left = svg.match(/\{\{[A-Z0-9_]+\}\}/g);
    errors.push(`${page}: 仍有未替换占位符 ${[...new Set(left)].join(', ')}`);
  }
  const chars = bodyChars(svg, slide, page);
  if (slide.role === 'content' && slide.density !== 'lean' && chars < 160) {
    warnings.push(`${page}: 正文约 ${chars} 字，低于 160`);
  }
  report.push({ page, key, chars });
  return { page, key, svg, chars };
}

const rendered = [];
for (let i = 0; i < slides.length; i += 1) {
  const slide = slides[i];
  const page = `P${String(i + 1).padStart(2, '0')}`;
  if (only && page !== only) continue;
  const result = composePage(slide, i);
  if (!result) continue;
  rendered.push(result);
  if (checkOnly) console.log(`[check] ${result.page} ${result.key} chars=${result.chars}`);
}

if (errors.length) {
  for (const w of warnings) console.error(`[warn] ${w}`);
  for (const e of errors) console.error(`[error] ${e}`);
  console.error(`\n[BLOCK] ${errors.length} 项错误；未写任何页面`);
  process.exit(1);
}

if (!checkOnly) {
  fs.mkdirSync(outDir, { recursive: true });
  const tocIndex = slides.findIndex((s) => s.role === 'toc');
  const tocPage = tocIndex >= 0 ? `P${String(tocIndex + 1).padStart(2, '0')}` : null;
  if (!only) {
    const keep = new Set(rendered.map((item) => item.page));
    if (tocPage) keep.add(tocPage);
    for (const name of fs.readdirSync(outDir)) {
      if (/^P\d{2,}\.svg$/.test(name) && !keep.has(name.slice(0, -4))) {
        fs.unlinkSync(path.join(outDir, name));
        console.log(`removed stale ${name}`);
      }
    }
  }
  for (const item of rendered) {
    fs.writeFileSync(path.join(outDir, `${item.page}.svg`), item.svg);
    console.log(`wrote ${item.page}.svg <- ${layouts.get(item.key).file}`);
  }
}

const summary = {
  schemaVersion: 1,
  project,
  layoutSystem: 'zhongtai-brand-core',
  pages: report.length,
  warnings: warnings.length,
  errors: errors.length,
  report,
};
for (const w of warnings) console.error(`[warn] ${w}`);
if (jsonOut) process.stdout.write(JSON.stringify(summary, null, 2) + '\n');
else console.log(`\n[summary] pages=${summary.pages} warnings=${summary.warnings} errors=${summary.errors}`);
if (errors.length) process.exit(1);
